<?php require_once __DIR__ . '/auth.php'; wajibLogin(); require_once __DIR__ . '/../config.php'; $pageTitle='Kelola Menu';$assetPrefix='../';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verifikasiAdminCsrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=max(0,(int)($_POST['price']??0));$cat=$_POST['category']??'Coffee';if($name!==''){if($id){$s=$pdo->prepare('UPDATE menu SET name=?,description=?,price=?,category=? WHERE id=?');$s->execute([$name,$desc,$price,$cat,$id]);}else{$s=$pdo->prepare('INSERT INTO menu(name,description,price,category) VALUES(?,?,?,?)');$s->execute([$name,$desc,$price,$cat]);}}}elseif($action==='toggle'){$s=$pdo->prepare('UPDATE menu SET active=1-active WHERE id=?');$s->execute([(int)$_POST['id']]);}header('Location: menu.php');exit;}$menus=$pdo->query('SELECT * FROM menu ORDER BY category,name')->fetchAll();require '../includes/header.php'; ?>
<span class="eyebrow">Pengaturan produk</span><h1 class="page-title">Kelola Menu</h1><p class="muted">Tambah menu baru atau ubah menu yang tersedia untuk pelanggan.</p><p><a class="btn light" href="index.php">Kembali ke Dashboard</a> <form method="post" action="logout.php" style="display:inline"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(adminCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><button class="btn light" type="submit">Logout</button></form></p><div class="layout"><section class="card"><h2 style="font-family:'Playfair Display'">Tambah menu</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(adminCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="save"><div class="form-row"><label>Nama menu</label><input class="input" name="name" required maxlength="120"></div><div class="form-row"><label>Deskripsi</label><input class="input" name="description" maxlength="255"></div><div class="form-row"><label>Harga (rupiah)</label><input class="input" name="price" type="number" min="0" required></div><div class="form-row"><label>Kategori</label><select name="category"><option>Coffee</option><option>Non Coffee</option><option>Mocktail</option><option>Tea Series</option><option>Add On</option><option>Snack</option></select></div><button class="btn">Simpan Menu</button></form></section><section><div class="grid"><?php foreach($menus as $m): ?><div class="card"><span class="pill"><?= htmlspecialchars($m['category']) ?></span><h3><?= htmlspecialchars($m['name']) ?></h3><p class="muted"><?= htmlspecialchars($m['description']) ?></p><p class="price"><?= rupiah($m['price']) ?></p><p><span class="status <?= $m['active']?'selesai':'dibatalkan' ?>"><?= $m['active']?'Aktif':'Nonaktif' ?></span></p><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(adminCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= $m['id'] ?>"><button class="btn light" type="submit"><?= $m['active']?'Nonaktifkan':'Aktifkan' ?></button></form></div><?php endforeach; ?></div></section></div>
